// ══════════════════════════════════════════════════════════
// GUEST_CHECKIN → إنشاء فاتورة مبيعات (Invoice)
// ══════════════════════════════════════════════════════════
const data = $input.first().json;
const nights = data.details?.nights || 1;
const rate_per_night = data.amount / nights;

// حساب المبالغ (إذا كان الـ amount يشمل الضرائب، نستخرج الصافي)
let net_amount = data.amount;
if (data.details?.tax_included) {
  // الإجمالي = الصافي × (1 + 14%) → الصافي = الإجمالي / 1.14
  net_amount = Math.round((data.amount / 1.14) * 100) / 100;
}

const invoice = {
  customer_name: data.details?.guest_name || 'Walk-in Guest',
  date: new Date().toISOString().split('T')[0],
  payment_terms: 0, // دفع فوري
  notes: `Room ${data.details?.room_number || 'N/A'} — ${nights} night(s) | Source: WhatsApp`,
  line_items: [
    {
      name:       `Room Accommodation — ${data.details?.room_number || 'Room'}`,
      description: `${nights} night(s) × ${rate_per_night} EGP/night`,
      quantity:   nights,
      rate:       Math.round((net_amount / nights) * 100) / 100,
      tax_name:   'VAT 14%',
      account_id: 'PLACEHOLDER_ROOM_REVENUE_ID' // يُستبدل بـ ID فعلي من الخطوة 4
    }
  ],
  tags: [{ tag_option_value: 'Rooms' }],
  payment_options: {
    payment_gateways: []
  }
};

// إضافة بيانات الدفع
if (data.payment_method === 'cash') {
  invoice.cash_as_payment = true;
}

return [{ json: { zoho_payload: invoice, original: data } }];

// ══════════════════════════════════════════════════════════
// CAFE_SHIFT → إنشاء قيد يومية (Journal Entry)
// ══════════════════════════════════════════════════════════
const data = $input.first().json;
const total_collected = data.amount; // الإجمالي المحصّل

// توزيع المبالغ:
// الإجمالي = صافي الإيراد × (1 + VAT 14%) × (1 + SC 12%)
// نعكس: صافي = الإجمالي / (1.14 × 1.12) = / 1.2768
const net_revenue   = Math.round((total_collected / 1.2768) * 100) / 100;
const vat_amount    = Math.round((net_revenue * 0.14) * 100) / 100;
const sc_amount     = Math.round((net_revenue * 0.12) * 100) / 100;
const check_total   = net_revenue + vat_amount + sc_amount;
// تصحيح الفروق في التقريب
const rounding_diff = Math.round((total_collected - check_total) * 100) / 100;

const now = new Date();
const shift_ref = `CAFE-${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${data.details?.shift || 'EVE'}`;

const journal = {
  journal_date: now.toISOString().split('T')[0],
  reference_number: shift_ref,
  notes: `Cafe shift closing — ${data.details?.shift || 'Evening'} | via WhatsApp`,
  line_items: [
    // Debit: الصندوق (ما دخل)
    {
      account_name: data.payment_method === 'card' ? 'POS Cash' : 'Main Cash',
      debit_or_credit: 'debit',
      amount: total_collected,
      description: 'Cash/POS collected'
    },
    // Credit: إيراد الكافيه (الصافي)
    {
      account_name: 'Cafe & Restaurant Sales',
      debit_or_credit: 'credit',
      amount: net_revenue + rounding_diff,
      description: 'Net F&B Revenue',
      tags: [{ tag_option_value: 'Cafe & Restaurant' }]
    },
    // Credit: ضريبة القيمة المضافة
    {
      account_name: 'Output VAT 14%',
      debit_or_credit: 'credit',
      amount: vat_amount,
      description: 'VAT 14% payable'
    },
    // Credit: رسم الخدمة
    {
      account_name: 'Service Charge Pool',
      debit_or_credit: 'credit',
      amount: sc_amount,
      description: 'Service Charge 12%'
    }
  ]
};

return [{ json: { zoho_payload: journal, original: data, breakdown: { net_revenue, vat_amount, sc_amount, total_collected } } }];

// ══════════════════════════════════════════════════════════
// EXPENSE_BILL → إنشاء فاتورة شراء (Bill) مع WHT
// ══════════════════════════════════════════════════════════
const data = $input.first().json;

// تحديد نسبة WHT حسب نوع المورد/الخدمة
const notes_lower = (data.details?.notes || '').toLowerCase();
const is_service = notes_lower.includes('صيان') ||
                   notes_lower.includes('خدم') ||
                   notes_lower.includes('service') ||
                   notes_lower.includes('مقاول');

const wht_rate      = is_service ? 0.03 : 0.01;
const wht_tax_name  = is_service ? 'WHT Services 3%' : 'WHT Purchase 1%';
const wht_amount    = Math.round((data.amount * wht_rate) * 100) / 100;
const net_payable   = Math.round((data.amount - wht_amount) * 100) / 100;

// تحديد حساب المصروف
let expense_account = 'Guest Amenities'; // افتراضي
if (notes_lower.includes('صيان') || notes_lower.includes('اصلاح')) {
  expense_account = 'Maintenance';
} else if (notes_lower.includes('كهرباء') || notes_lower.includes('ماء') || notes_lower.includes('غاز')) {
  expense_account = 'Utilities';
} else if (notes_lower.includes('طعام') || notes_lower.includes('مشروب') || notes_lower.includes('خام')) {
  expense_account = 'F&B COGS';
}

const now = new Date();
const bill = {
  vendor_name: data.details?.vendor_name || 'Unknown Vendor',
  date: now.toISOString().split('T')[0],
  due_date: now.toISOString().split('T')[0],
  reference_number: `BILL-${Date.now()}`,
  notes: `WHT ${wht_rate*100}% applied — Net payable: ${net_payable} EGP | via WhatsApp`,
  line_items: [
    {
      account_name: expense_account,
      description: data.details?.notes || 'Purchase/Expense',
      quantity: 1,
      rate: data.amount,
      tax_name: wht_tax_name
    }
  ],
  tags: [{ tag_option_value: 'General & Admin' }]
};

return [{ json: {
  zoho_payload: bill,
  original: data,
  wht_summary: { wht_rate, wht_amount, net_payable, expense_account, wht_tax_name }
}}];

// دمج نتائج الـ 3 فروع في output موحد للـ Auto-Response
const input = $input.first().json;
const response = input.response || input;
const original = $('Route by Transaction Type').item?.json || {};

const type = original.transaction_type;
let ref_number = 'N/A';
let success = false;

if (response.code === 0 || response.invoice || response.journal || response.bill) {
  success = true;
  if (response.invoice)      ref_number = response.invoice.invoice_number;
  else if (response.journal) ref_number = response.journal.reference_number;
  else if (response.bill)    ref_number = response.bill.bill_number;
}

return [{ json: {
  success,
  transaction_type: type,
  ref_number,
  amount: original.amount,
  from_number: original.from_number,
  contact_name: original.contact_name,
  zoho_response: response
}}];
